/* ============================================================
   BANCO FICTÍCIO DE RH / DEI PARA PRÁTICA DE SQL — VERSÃO 1000 FUNCIONÁRIOS
   Compatível com SQL Server (T-SQL)
   Mesma estrutura de tabelas do banco_rh_dei.sql original — apenas o volume
   e a distribuição dos dados mudam, para simular uma empresa de médio porte.
   ============================================================ */

-- Se quiser, crie um banco próprio antes de rodar o script:
-- CREATE DATABASE RH_DEI;
-- GO
-- USE RH_DEI;
-- GO

/* ------------------------------------------------------------
   1. TABELAS
   ------------------------------------------------------------ */

CREATE TABLE departamentos (
    id_departamento INT PRIMARY KEY,
    nome_departamento VARCHAR(50) NOT NULL,
    centro_custo VARCHAR(20)
);

CREATE TABLE cargos (
    id_cargo INT PRIMARY KEY,
    nome_cargo VARCHAR(50) NOT NULL,
    nivel_hierarquico VARCHAR(30), -- Ex: Operacional, Coordenação, Gerência, Diretoria
    faixa_salarial_min DECIMAL(10,2),
    faixa_salarial_max DECIMAL(10,2)
);

CREATE TABLE funcionarios (
    id_funcionario INT PRIMARY KEY,
    nome VARCHAR(100) NOT NULL,
    email VARCHAR(100),
    genero VARCHAR(20),           -- Feminino, Masculino, Não-binário, Não informado
    raca_etnia VARCHAR(30),       -- Branca, Preta, Parda, Amarela, Indígena, Não informado
    data_nascimento DATE,
    data_admissao DATE,
    data_desligamento DATE NULL,  -- NULL = ainda ativo
    id_departamento INT,
    id_cargo INT,
    salario DECIMAL(10,2),
    FOREIGN KEY (id_departamento) REFERENCES departamentos(id_departamento),
    FOREIGN KEY (id_cargo) REFERENCES cargos(id_cargo)
);

CREATE TABLE avaliacoes (
    id_avaliacao INT PRIMARY KEY,
    id_funcionario INT,
    data_avaliacao DATE,
    nota DECIMAL(3,1), -- 0.0 a 10.0
    tipo_avaliacao VARCHAR(30), -- Desempenho, 360, PDI
    FOREIGN KEY (id_funcionario) REFERENCES funcionarios(id_funcionario)
);

CREATE TABLE promocoes (
    id_promocao INT PRIMARY KEY,
    id_funcionario INT,
    data_promocao DATE,
    cargo_anterior VARCHAR(50),
    cargo_novo VARCHAR(50),
    FOREIGN KEY (id_funcionario) REFERENCES funcionarios(id_funcionario)
);

